####################################################################################################
# Function to Handle Study-Specific Data Frame Exceptions
####################################################################################################

fun_dgsk_exceptions <- function(stu_dfs, study_id = "10555") {
  # Arguments:
  # - stu_dfs: (named list of data frames) A list of data frames for a specific study, generated by 
  # the `fun_dgsk_readdfs` function.
  # - study_id: (string) The unique identifier for the study being processed. 
  # Output:
  # - stu_dfs: (named list of data frames) The modified list of data frames after applying 
  # study-specific exceptions and adjustments.
  
  # Missing variables (rename from other column) ---------------------------------------------------
  ## Missing elig_ma (rename from elig or elig_bo)
  if(!any(names(stu_dfs$pid) == "elig_ma") & any(names(stu_dfs$pid) == "elig")) {
    stu_dfs$pid <- rename(stu_dfs$pid, elig_ma = elig) 
  } else if(!any(names(stu_dfs$pid) == "elig_ma") & any(names(stu_dfs$pid) == "elig_bo")) {
    stu_dfs$pid <- rename(stu_dfs$pid, elig_ma = elig_bo) 
  } 
  ## Missing seroname (rename from compo_un)
  if(!any(names(stu_dfs$sero) == "seroname") & any(names(stu_dfs$sero) == "compo")) {
    stu_dfs$sero <- rename(stu_dfs$sero, seroname = compo)
  }
  ## Missing p_rdat (rename from actrdate)
  if(!any(names(stu_dfs$expo) == "p_rdat") & any(names(stu_dfs$expo) == "actrdate")) {
    stu_dfs$expo <- rename(stu_dfs$expo, p_rdat = actrdate) 
  }
  ## Missing raw_date (rename from actrdate)
  if(!any(names(stu_dfs$dates) == "raw_date") & any(names(stu_dfs$dates) == "actrdate")) {
    stu_dfs$dates <- rename(stu_dfs$dates, raw_date = actrdate) 
  }
  
  # Single manual exceptions per study (numerical order) -------------------------------------------
  
  ## Missing cty_name (adding from protocol) -------------------------------------------------------
  if(study_id == "101197") stu_dfs$pid <- mutate(stu_dfs$pid, cty_nam = "South Korea")
  if(study_id == "109861") stu_dfs$pid <- mutate(stu_dfs$pid, cty_nam = "Taiwan")
  if(study_id == "444563-020") stu_dfs$pid <- mutate(stu_dfs$pid, cty_nam = "Costa Rica")
  if(study_id == "759348-007") stu_dfs$pid <- mutate(stu_dfs$pid, cty_nam = "Germany")
  # if(study_id == "763674-001") stu_dfs$pid <- mutate(stu_dfs$pid, cty_nam = "Dominican Republic")
  # if(study_id == "763674-002") stu_dfs$pid <- mutate(stu_dfs$pid, cty_nam = "Dominican Republic")
  
  ## Missing method (adding from protocol) ---------------------------------------------------------
  # if(study_id == "115158") { stu_dfs$sero <- mutate(stu_dfs$sero, method = case_when(
  #   str_detect(seroname, "polio") ~ "prnt", .default = "elisa")) }
  
  # Complex manual exceptions per study (numerical order) ------------------------------------------
  
  ## 100478 ----------------------------------------------------------------------------------------
  if(study_id == "100478") {
    # Missing vaccines opv (adding from vacc_con)
    stu_dfs$expo <- stu_dfs$expo %>%
      bind_rows(readRDS(glue("{dirs$server_vacc_con}/gsk_100478_vacc_con.rds")) %>%
                  rename_with(tolower) %>%
                  mutate(pid = as.character(pid),
                         vaccine = case_when(
                           tradname %in% c("OPV", "POLIO", "ORAL POLIO VACCINE", "ORAL POLIO VACCINE", 
                                          "ORAL POLIO VACCINEI", "IOPV", "OPVOP", "O[PV", 
                                          "ORAL POLI VACCINE", "0RAL POLIO VACCINE", "0PV") ~ "opv",
                           .default = tradname),
                         p_rdat = as.character(medsrdat),
                         v_adm = "Y") %>%
                  left_join(distinct(stu_dfs$pid, pid, group_nb), by = join_by(pid)) %>%
                  filter(vaccine == "opv") %>% 
                  select(pid, vaccine, p_rdat, group_nb, v_adm)) %>%
      arrange(pid, activity)
  }
  
  ## 100480 ----------------------------------------------------------------------------------------
  if(study_id == "100480") {
    # Read in study 104727
    temp_folders_study <- c("104727" = "dtp_hbv_hib")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["104727"], cdi = FALSE)
    
    # Missing dates (adding from study 104727)
    stu_dfs$dates <- stu_dfs2$dates
    # Missing sero (adding from study 104727)
    stu_dfs$sero <- stu_dfs2$sero %>%
      # Surplus seroname men (eliminate log and cut_off == 8)
      filter(!(seroname %in% c("N MEN A AB", "SBA-MENA L10")))
  }
  
  ## 101222 ----------------------------------------------------------------------------------------
  if(study_id == "101222") {
    # Missing elig_ma (adding from elim criteria)
    stu_dfs$pid <- mutate(stu_dfs$pid, elig_ma = case_when(
      !is.na(elim_r001) | !is.na(elim_s001) | !is.na(elim_v001) ~ "EI_101222",
      !is.na(elim_r003) | !is.na(elim_s003) | !is.na(elim_v003) ~ "EI_bo104065",
      .default = ""), 
      # Incomplete treatmnt (binding treatmnt studies)
      treatmnt = as.character(glue("{treat001}_{treat003}")))
  }
  
  ## 101223 ----------------------------------------------------------------------------------------
  if(study_id == "101223") {
    # Missing elig_ma (adding from elim criteria)
    stu_dfs$pid <- mutate(stu_dfs$pid, elig_ma = case_when(
      !is.na(elim_r002) | !is.na(elim_s002) | !is.na(elim_v002) ~ "EI_101223",
      !is.na(elim_r006) | !is.na(elim_s006) | !is.na(elim_v006) ~ "EI_bo106602",
      .default = ""),
      # Incomplete treatmnt (binding treatmnt studies)
      treatmnt = as.character(glue("{treat002}_{treat006}")))
  }
  
  ## 101858 ----------------------------------------------------------------------------------------
  if(study_id == "101858") {
    
    # Read in study 102015 and 107824
    temp_folders_study <- c("102015" = "hib_men", "107824" = "hib_men")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["102015"], cdi = FALSE)
    stu_dfs3 <- fun_dgsk_readdfs(temp_folders_study["107824"], cdi = FALSE)
    
    # Missing booster study and follow up study (adding from study 102015 and 107824) 
    stu_dfs$pid <- stu_dfs$pid %>%
      left_join(select(stu_dfs2$pid, pid, elig_ma, treatmnt) %>%
                  rename(elig_ma_002 = elig_ma, treatmnt_002 = treatmnt), 
                by = join_by(pid)) %>%
      left_join(select(stu_dfs3$pid, pid, elig_ma) %>%
                  mutate(elig_ma = replace_na(elig_ma, "")) %>%
                  rename(elig_ma_003 = elig_ma), by = join_by(pid)) %>%
      # Incomplete treatmnt (binding treatmnt studies)
      mutate(treatmnt = as.character(glue("{treatmnt}_{treatmnt_002}")))
    stu_dfs$expo <- bind_rows(stu_dfs$expo, stu_dfs2$expo)
    stu_dfs$dates <- bind_rows(stu_dfs$dates, stu_dfs2$dates) %>%
      bind_rows(filter(stu_dfs3$dates, activity != 50))
    stu_dfs$sero <- bind_rows(stu_dfs$sero, stu_dfs2$sero) %>%
      bind_rows(stu_dfs3$sero) %>%
      # Surplus seroname men (eliminate cut_off != 8)
      filter(!(seroname %in% c("hSBA-MenC", "hSBA-MenY", "hSBA-MenC (updated)", 
                               "hSBA-MenC (original)", "N MEN Y L3V S1975 AB")))
  }
  
  ## 102247 ----------------------------------------------------------------------------------------
  if(study_id == "102247") {
    # Missing concomitant vaccines (adding from dates)
    stu_dfs$expo <- stu_dfs$expo %>%
      bind_rows(filter(stu_dfs$dates, type_lst %in% c("PRV", "IRX", "MEN", "IPH")) %>%
                  mutate(vaccine = case_when(type_lst == "PRV" ~ "prevnar",
                                             type_lst == "IRX" ~ "infanrix hexa",
                                             type_lst == "MEN" ~ "meningitec vaccine",
                                             type_lst == "IPH" ~ "dtpa_ipv_hib"),
                         p_rdat = raw_date,
                         v_adm = "Y") %>%
                  filter(!is.na(raw_date)) %>% 
                  select(pid, vaccine, p_rdat, group_nb, v_adm))
    
    # Surplus seroname HBV.S AB	duplicated (eliminate)
    stu_dfs$sero <- filter(stu_dfs$sero, seroname != "HBV.S AB")
  }
  
  ## 103388 ----------------------------------------------------------------------------------------
  if(study_id == "103388") {
    # Missing cty_nam (adding from demo file) 
    stu_dfs$pid <- select(stu_dfs$pid, -cty_nam) %>%
      left_join(select(stu_dfs$demo, pid, cty_nam), by = join_by(pid))
  }
  
  ## 103477 ----------------------------------------------------------------------------------------
  if(study_id == "103477") {
    # Surplus seroname rota (eliminate test with only NAs) 
    stu_dfs$sero <- filter(stu_dfs$sero, seroname != "ROTA AG")
  }
  
  ## 103478 ----------------------------------------------------------------------------------------
  if(study_id == "103478") {
    # Missing cty_nam (adding from protocol) 
    stu_dfs$pid <- mutate(stu_dfs$pid, cty_nam = "South Korea")
    
    # Unclear vaccine (na if TREATMENT A)
    stu_dfs$expo <- mutate(stu_dfs$expo, vaccine = na_if(vaccine, "TREATMENT A"))
  }
  
  ## 103488 ----------------------------------------------------------------------------------------
  if(study_id == "103488") {
    # Missing group_nb (adding from pid)
    stu_dfs$expo <- left_join(stu_dfs$expo,select(stu_dfs$pid, pid, group_nb), by = join_by(pid))
    
    # Surplus seroname opsono 18c (eliminate CDC)
    stu_dfs$sero <- filter(stu_dfs$sero, seroname != "OPSONO-18C CDC")
  }
  
  ## 103974 ----------------------------------------------------------------------------------------
  if(study_id == "103974") {
    # Read in study 104056 and 109664
    temp_folders_study <- c("104056" = "hib_men",
                            "109664" = "hib_men")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["104056"], cdi = FALSE)
    stu_dfs3 <- fun_dgsk_readdfs(temp_folders_study["109664"], cdi = FALSE)
    
    # Missing booster study and follow up study (adding from study 104056 and 109664)
    stu_dfs$pid <- stu_dfs$pid %>%
      left_join(select(stu_dfs2$pid, pid, elig_ma, treatmnt) %>%
                  rename(elig_ma_002 = elig_ma,
                         treatmnt_002 = treatmnt), by = join_by(pid)) %>%
      left_join(select(stu_dfs3$pid, pid, elig_y1) %>%
                  rename(elig_ma_003 = elig_y1), by = join_by(pid)) %>%
      # Incomplete treatmnt (binding treatmnt studies)
      mutate(treatmnt = as.character(glue("{treatmnt}_{treatmnt_002}"))) %>%
      # Missing cty_nam (adding from protocol) 
      mutate(cty_nam = case_when(country == 1 ~ "United Kingdom",
                                 country == 2 ~ "Poland"))
    stu_dfs$expo <- bind_rows(stu_dfs$expo, stu_dfs2$expo)
    stu_dfs$dates <- bind_rows(stu_dfs$dates, stu_dfs2$dates) %>%
      bind_rows(stu_dfs3$dates)
    stu_dfs$sero <- bind_rows(stu_dfs$sero, stu_dfs2$sero) %>%
      bind_rows(stu_dfs3$sero) 
  }
  
  ## 103992 ----------------------------------------------------------------------------------------
  if(study_id == "103992") {
    stu_dfs$expo <- stu_dfs$expo %>%
      # Missing vaccines dtpw_hbv (adding from protocol activities 10-20-40 all)
      bind_rows(distinct(stu_dfs$dates, pid, raw_date, activity) %>%
                  left_join(select(stu_dfs$pid, pid, group_nb), by = join_by(pid)) %>%
                  filter(raw_date != "" & activity %in% c("10", "20", "40")) %>%
                  mutate(vaccine = "dtpw_hbv",
                         v_adm = "Y") %>%
                  rename(p_rdat = raw_date)) %>%
      # Missing vaccines opv (adding from protocol activities 20-40 or 30-50 opv groups)
      bind_rows(distinct(stu_dfs$dates, pid, raw_date, activity) %>%
                  left_join(select(stu_dfs$pid, pid, group_nb), by = join_by(pid)) %>%
                  filter(raw_date != "" & group_nb %in% c("1", "2") & activity %in% c("20", "40")) %>%
                  mutate(vaccine = "opv",
                         v_adm = "Y") %>%
                  rename(p_rdat = raw_date)) %>%
      bind_rows(distinct(stu_dfs$dates, pid, raw_date, activity) %>%
                  left_join(select(stu_dfs$pid, pid, group_nb), by = join_by(pid)) %>%
                  filter(raw_date != "" & group_nb %in% c("3", "4") & activity %in% c("30", "50")) %>%
                  mutate(vaccine = "opv",
                         v_adm = "Y") %>%
                  rename(p_rdat = raw_date)) 
  }
  
  ## 104021 ----------------------------------------------------------------------------------------
  if(study_id == "104021") {
    # Missing vaccines opv (adding from vacc_con)
    stu_dfs$expo <- stu_dfs$expo %>% 
      bind_rows(readRDS(glue("{dirs$server_vacc_con}/gsk_104021_vacc_con.rds")) %>%
                  rename_with(tolower) %>%
                  mutate(pid = as.character(pid),
                         vaccine = as.character(tradname),
                         p_rdat = as.character(medsrdat),
                         v_adm = "Y") %>%
                  left_join(distinct(stu_dfs$pid, pid, group_nb), by = join_by(pid)) %>%
                  select(pid, vaccine, p_rdat, group_nb, v_adm)) %>%
      arrange(pid, activity)
    
    # Surplus seroname hbv (eliminate serotest 8 TNR) 
    stu_dfs$sero <- filter(stu_dfs$sero, serotest != "8")
  }
  
  ## 104480 ----------------------------------------------------------------------------------------
  if(study_id == "104480") {
    # Surplus seroname rota (eliminate test with only NAs) 
    stu_dfs$sero <- filter(stu_dfs$sero, seroname != "ROTA AG (WARD)")
  }
  
  ## 104567 ----------------------------------------------------------------------------------------
  if(study_id == "104567") {
    # Missing elig_ma (adding from elim criteria)
    stu_dfs$pid <- mutate(stu_dfs$pid, elig_ma = case_when(
      !is.na(elim_r131) | !is.na(elim_s131) | !is.na(elim_v131) ~ "EI_104567",
      !is.na(elim_r134) | !is.na(elim_s134) | !is.na(elim_v134) ~ "EI_bo111535",
      .default = ""),
      # Incomplete treatmnt (binding treatmnt studies)
      treatmnt = as.character(glue("{treat131}_{treat134}")))
    
    # Contained study with repeated activities (fixing to sequential activities) 
    stu_dfs$expo <- mutate(stu_dfs$expo, activity = case_when(
      study == "111535" & activity == "10" ~ "50",
      .default = activity))
    stu_dfs$dates <- mutate(stu_dfs$dates, activity = case_when(
      study == "111535" & activity == "10" ~ "50",
      study == "111535" & activity == "20" ~ "60",
      .default = activity))
    stu_dfs$sero <- mutate(stu_dfs$sero, activity = case_when(
      study == "111535" & activity == "10" ~ "50",
      study == "111535" & activity == "20" ~ "60",
      .default = activity)) %>%
      # Missing cut-off (adding from protocol)
      mutate(cut_off = case_when(
        is.na(cut_off) & method == "ELISA" & seroname == "ANTI-PRN" ~ "5",
        .default = cut_off))
  }
  
  ## 104733 ----------------------------------------------------------------------------------------
  if(study_id == "104733") {
    # Unclear vaccine (ipol to opv)
    stu_dfs$expo <- mutate(stu_dfs$expo, vaccine = case_when(vaccine == "IPOL" ~ "opv",
                                                             .default = vaccine))
  }
  
  ## 104977 ----------------------------------------------------------------------------------------
  if(study_id == "104977") {
    # Missing vaccine (adding from treatmnt)
    stu_dfs$expo <- stu_dfs$expo %>%
      left_join(distinct(stu_dfs$pid, pid, treatmnt), by = join_by(pid)) %>%
      mutate(vaccine = treatmnt)
  }
  
  ## 105539 ----------------------------------------------------------------------------------------
  if(study_id == "105539") {
    # Read in study 105539
    temp_folders_study <- c("105539" = "strep")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["105539"], cdi = FALSE, info_files = TRUE)
    
    # Missing demo (adding from study 105539 additional data frame)
    stu_dfs$demo <- stu_dfs2$gsk_105539_c_w_demog_v02.rds
    # Missing dates (adding from study 105539 additional data frame)
    stu_dfs$dates <- stu_dfs2$gsk_105539_c_w_dates_v02.rds
    
    # Missing group_nb (adding from pid)
    stu_dfs$expo <- stu_dfs$expo %>%
      left_join(select(stu_dfs$pid, pid, group_nb, cty_nam), by = join_by(pid)) %>%
      # Missing vaccines hbv_ipv_hib (adding from protocol by country)
      mutate(vaccine = case_when(
        vaccine == "DTPA VACCINE" & cty_nam %in% c("Slovakia", "Sweden") ~ "DTPa-HBV-IPV/Hib",
        vaccine == "DTPA VACCINE" & cty_nam %in% c("Norway", "Denmark") ~ "DTPa-IPV/Hib",
        .default = vaccine))
  }
  
  ## 105553 ----------------------------------------------------------------------------------------
  if(study_id == "105553") {
    # Read in study 105553
    temp_folders_study <- c("105553" = "strep")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["105553"], cdi = FALSE, info_files = TRUE)
    
    # Missing demo (adding from study 105553 additional data frame)
    stu_dfs$demo <- stu_dfs2$gsk_105553_c_w_demog_v02.rds
    # Missing dates (adding from study 105553 additional data frame)
    stu_dfs$dates <- stu_dfs2$gsk_105553_c_w_dates_v02.rds
  }
  
  ## 105554 ----------------------------------------------------------------------------------------
  if(study_id == "105554") {
    # Read in study 105554
    temp_folders_study <- c("105554" = "strep")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["105554"], cdi = FALSE, info_files = TRUE)
    
    # Missing demo (adding from study 105554 additional data frame)
    stu_dfs$demo <- stu_dfs2$gsk_105554_c_w_demog.rds
    # Missing dates (adding from study 105554 additional data frame)
    stu_dfs$dates <- stu_dfs2$gsk_105554_c_w_dates.rds
  }
  
  ## 105722 ----------------------------------------------------------------------------------------
  if(study_id == "105722") {
    stu_dfs$expo <- stu_dfs$expo %>%
      # Missing vaccines dtpw (adding from protocol activities 10-20-30 all)
      bind_rows(filter(stu_dfs$expo, activity %in% c("10", "20", "30")) %>%
                  filter(p_rdat != "") %>%
                  distinct(pid, p_rdat, group_nb, v_adm) %>%
                  mutate(vaccine = "dtpw")) %>%
      # Missing vaccines opv (adding from protocol activities 10-20-30 all)
      bind_rows(filter(stu_dfs$expo, activity %in% c("10", "20", "30")) %>%
                  filter(p_rdat != "") %>%
                  distinct(pid, p_rdat, group_nb, v_adm) %>%
                  mutate(vaccine = "opv")) %>%
      # Missing vaccines hbv (adding from protocol activities 10-30 all)
      bind_rows(filter(stu_dfs$expo, activity %in% c("10", "30")) %>%
                  filter(p_rdat != "") %>%
                  distinct(pid, p_rdat, group_nb, v_adm) %>%
                  mutate(vaccine = "hbv"))
  }
  
  ## 105910 ----------------------------------------------------------------------------------------
  if(study_id == "105910") {
    # Missing elig_ma (adding from elim criteria)
    stu_dfs$pid <- mutate(stu_dfs$pid, elig_ma = case_when(
      !is.na(elim_r109) | !is.na(elim_s109) | !is.na(elim_v109) ~ "EI_105910", 
      !is.na(elim_r117) | !is.na(elim_s117) | !is.na(elim_v117) ~ "EI_bo110478",
      .default = ""),
      # Incomplete treatmnt (binding treatmnt studies)
      treatmnt = as.character(glue("{treat109}_{treat117}")))
    
    # Contained study with repeated activities (fixing to sequential activities)
    stu_dfs$expo <- mutate(stu_dfs$expo, activity = case_when(
      study == "110478" & activity == "10" ~ "50",
      .default = activity))
    stu_dfs$dates <- mutate(stu_dfs$dates, activity = case_when(
      study == "110478" & activity == "10" ~ "50",
      study == "110478" & activity == "20" ~ "60",
      .default = activity))
    stu_dfs$sero <- mutate(stu_dfs$sero, activity = case_when(
      study == "110478" & activity == "10" ~ "50",
      study == "110478" & activity == "20" ~ "60",
      .default = activity))
  }
  
  ## 106208 ----------------------------------------------------------------------------------------
  if(study_id == "106208") {
    # Read in study 106208
    temp_folders_study <- c("106208" = "strep")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["106208"], cdi = FALSE, info_files = TRUE)
    
    # Missing demo (adding from study 106208 additional data frame)
    stu_dfs$demo <- stu_dfs2$gsk_106208_c_w_demog.rds
    # Missing dates (adding from study 106208 additional data frame)
    stu_dfs$dates <- stu_dfs2$gsk_106208_c_w_dates.rds
  }
  
  ## 106260 ----------------------------------------------------------------------------------------
  if(study_id == "106260") {
    stu_dfs$expo <- stu_dfs$expo %>%
      # Missing vaccines dtp_hib_ipv_hbv (adding from vacc_con)
      bind_rows(read.csv(glue("{dirs$server_bg}/rota/106260/gsk_106260_vacc_con.csv")) %>%
                  rename_with(tolower) %>%
                  mutate(pid = as.character(pid),
                         vaccine = as.character(gsk_mod),
                         p_rdat = as.character(medsrdat),
                         v_adm = "Y") %>%
                  left_join(distinct(stu_dfs$pid, pid, group_nb), by = join_by(pid)) %>%
                  filter(vaccine %in% c("DTPa+HBV+HIB+IPV", "DTPA+HBV+HIB+IPV")) %>%
                  select(pid, vaccine, p_rdat, group_nb, v_adm))
  }
  
  ## 106445 ----------------------------------------------------------------------------------------
  if(study_id == "106445") {
    # Surplus seroname men (eliminate menc extra)
    stu_dfs$sero <- filter(stu_dfs$sero, !(compo %in% c("N MEN C L3V C11 AB")))
  }
  
  ## 106786 ----------------------------------------------------------------------------------------
  if(study_id == "106786") {
    # Missing elig_ma (adding from elim criteria)
    stu_dfs$pid <- mutate(stu_dfs$pid, elig_ma = case_when(
      !is.na(elim_r116) | !is.na(elim_s116) | !is.na(elim_v116) ~ "EI_106786",
      !is.na(elim_r120) | !is.na(elim_s120) | !is.na(elim_v120) ~ "EI_bo111344",
      .default = ""),
      # Incomplete treatmnt (binding treatmnt studies)
      treatmnt = as.character(glue("{treat116}_{treat120}")))
    
    # Missing group_nb (adding from pid)
    stu_dfs$expo <- left_join(stu_dfs$expo, distinct(stu_dfs$pid, pid, group_nb), by = join_by(pid))
    
    # Contained study with repeated activities (fixing to sequential activities)
    stu_dfs$expo <- mutate(stu_dfs$expo, activity = case_when(
      study == "111344" & activity == "10" ~ "50",
      .default = activity))
    stu_dfs$dates <- mutate(stu_dfs$dates, activity = case_when(
      study == "111344" & activity == "10" ~ "50",
      study == "111344" & activity == "20" ~ "60",
      .default = activity))
