      rename(v_adm = p_ap)
    
    # Missing raw_date (adding from per column dates)
    stu_dfs$dates <- select(stu_dfs$dates, pid, starts_with("bl_")) %>%
      pivot_longer(cols = starts_with("bl_"), values_to = "raw_date") %>%
      separate(name, into = c("type_lst", "activity")) %>%
