    stu_dfs$sero <- stu_dfs2$gsk_217744_085_r_labo.rds %>%
      # Missing num_res (adding from per column num_res)
      pivot_longer(cols = starts_with("x_"), values_to = "num_res") %>%
      # Missing seroname, method, activity, cut_off, unit (adding from instructions)
      left_join(read_excel(
        glue("{dirs$server_bg}/dtp_hbv_polio/217744-085/gsk-217744-085-instructions.xls")) %>%
          select(name, label) %>%
          filter(str_detect(name, "X_")) %>%
          separate(label, into = c("seroname", "method", "prepost","unit", "lab"), sep = "\\*",
                   fill = "right") %>%
          mutate(
            name = tolower(name),
            activity = case_when(str_detect(prepost, "PRE") ~ "10",
                                 str_detect(prepost, "POST") ~ "40"),
            cut_off = case_when(seroname %in% c("Anti-TetanusIgG", "Anti-DiphteriaIgG") ~ "0.1",
                                seroname %in% c("Anti-PtIgG", "Anti-PRNIgG", "Anti-FHAIgG") ~ "5",
                                seroname %in% c("IgTOTAnti-HBS") ~ "10",
                                seroname %in% c("Anti-PRPIgGTot") ~ "0.15",
                                str_detect(seroname, "POLIO") ~ "8",
                                str_detect(seroname, "S.pneumonia") ~ "0.05"),
            # Add min val according to other studies 
            cut_min = case_when(seroname %in% c("Anti-TetanusIgG", "Anti-DiphteriaIgG") ~ "0.05",
                                seroname %in% c("Anti-PtIgG", "Anti-PRNIgG", "Anti-FHAIgG") ~ "2.5",
                                seroname %in% c("IgTOTAnti-HBS") ~ "5",
                                seroname %in% c("Anti-PRPIgGTot") ~ "0.075",
                                str_detect(seroname, "POLIO") ~ "4",
                                str_detect(seroname, "S.pneumonia") ~ "0.025")) %>%
          select(name, method, seroname, activity, cut_off, cut_min, unit), 
        by = join_by(name))  %>%
      # Unclear num_res (0 if <)
      mutate(num_res = as.character(suppressWarnings(as.numeric(
        case_when(str_detect(num_res, "<") ~ cut_min, .default = num_res)))))
  }
  
