        center %in% c("4") ~ "Argentina",
        center %in% c("1", "2", "5", "6") ~ "Costa Rica"),
        # NAs in elig_ma (replace "")
        elig_ma = case_when(is.na(center) ~ "I", .default = ""))
    # Missing type_lst (adding from sero)
    stu_dfs$dates <- stu_dfs$dates %>%
      mutate(type_lst = case_when(activity %in% unique(stu_dfs$sero$activity) ~ "BL"))
    # Surplus method axsym and dipht and men (eliminate method and repeated test)
    stu_dfs$sero <- stu_dfs$sero %>%
      filter(method != "ELISA(MEP)")
  }
  
  ## 402764-004 ------------------------------------------------------------------------------------
  if(study_id == "402764-004") {
    # Missing cty_nam (adding from protocol) 
    stu_dfs$pid <- mutate(stu_dfs$pid, cty_nam = "Dominican Republic")
    
    # Unclear vaccine (na if TREATMENT B)
    stu_dfs$expo <- mutate(stu_dfs$expo, vaccine = na_if(vaccine, "TREATMENT B"))
  }

  ## 444563-004 ------------------------------------------------------------------------------------
  if(study_id == "444563-004") {
    # Surplus seroname IGTOT rota (Eliminate repeated test)
    stu_dfs$sero <- filter(stu_dfs$sero, !(str_detect(seroname, "IGTOT")))
  }
  
  ## 444563-005 ------------------------------------------------------------------------------------
  if(study_id == "444563-005") {
    # Missing vaccines dtp_hib_pn_ipv_hbv_men (adding from vacc_con)
    stu_dfs$expo <- stu_dfs$expo %>%
      bind_rows(read.csv((glue("{dirs$server_bg}/rota/444563-005/gsk_444563_005_vacc_con.csv"))) %>%
                  rename_with(tolower) %>%
                  mutate(vaccine = as.character(mod_trad),
                         pid = as.character(pid),
                         p_rdat = medsrdat,
                         v_adm = "Y") %>%
                  filter(vaccine %in% c("INFANRIX", "HIB", "PREVNAR", "IPOL", "HEP.B", "PENTACEL",
                                        "MENJUGATE")) %>%
                  left_join(stu_dfs$pid, by = join_by(pid)) %>%
                  select(pid, vaccine, p_rdat, group_nb, v_adm))
  }
  
  ## 444563-007 ------------------------------------------------------------------------------------
  if(study_id == "444563-007") {
    # Missing vaccines dtp_hib_ipv_hbv (adding from vacc_con)
    stu_dfs$expo <- stu_dfs$expo %>%
      bind_rows(read.csv((glue("{dirs$server_bg}/rota/444563-007/gsk_444563_007_vacc_con.csv"))) %>%
                  rename_with(tolower) %>%
                  # Duplicated vaccinations
                  filter(!(pid == "1231" & seq_no == "2")) %>%
                  filter(!(pid == "199" & seq_no == "2")) %>%
                  filter(!(pid == "2852" & seq_no == "2")) %>%
                  filter(!(pid == "746" & seq_no == "4")) %>%
                  filter(!(pid == "1067" & seq_no == "4")) %>%
                  mutate(vaccine = as.character(mod_trad),
                         pid = as.character(pid),
                         p_rdat = medsrdat,
                         v_adm = "Y") %>%
                  filter(vaccine %in% c("DTPa-IPV-Hib", "DTPa-IPV-Hib+HEP", "HEPB")) %>%
                  left_join(stu_dfs$pid, by = join_by(pid)) %>%
                  select(pid, vaccine, p_rdat, group_nb, v_adm))
  }
  
  ## 444563-013 ------------------------------------------------------------------------------------
  if(study_id == "444563-013") {
    # Missing cty_nam (adding from protocol) 
    stu_dfs$pid <- mutate(stu_dfs$pid, cty_nam = "South Africa")
    
    # Unclear seroname (IGA-ROTA to anti_rota_iga_rix)
    stu_dfs$sero <- mutate(stu_dfs$sero, seroname = case_when(
      seroname == "IGA-ROTA" ~ "anti_rota_iga_rix", .default = seroname))
  }
  
  ## 711202-001 ------------------------------------------------------------------------------------
  if(study_id == "711202-001") {
    # Surplus seroname men (Eliminate repeated test)
    stu_dfs$sero <- filter(stu_dfs$sero, !(seroname %in% c("IgSBA-MenC19", "SBA-MenC 11", 
                                                           "SBA-MenC 4PARA")))
  }
  
  ## 759346-001 ------------------------------------------------------------------------------------
  if(study_id == "759346-001") {
    # Read in study 759346-002
    temp_folders_study <- c("759346-002" = "dtp_hbv_hib")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["759346-002"], cdi = FALSE)
    
    # Missing follow up study (adding study 759346-002)
    stu_dfs$pid <- stu_dfs$pid %>%
      left_join(select(stu_dfs2$pid, pid, elig_ma, treatmnt) %>%
                  rename(elig_ma_002 = elig_ma, treatmnt_002 = treatmnt), by = join_by(pid)) %>%
      # Incomplete treatmnt (binding treatmnt studies)
      mutate(treatmnt = as.character(glue("{treatmnt}_{treatmnt_002}"))) %>%
      # Missing cty_nam (adding from protocol) 
      mutate(cty_nam = "Philippines")
    
    stu_dfs$expo <- bind_rows(stu_dfs$expo, stu_dfs2$expo)
    stu_dfs$dates <- bind_rows(stu_dfs$dates, stu_dfs2$dates)
    stu_dfs$sero <- bind_rows(stu_dfs$sero, stu_dfs2$sero) %>%
      # Surplus method axsym and dipht and men (eliminate method and repeated test)
      filter(method != "AXSYM") %>%
      filter(!(seroname %in% c("IGG DIPHTERIA", "SBA-MenA L10")))
  }
  
  ## 759348-001 ------------------------------------------------------------------------------------
  if(study_id == "759348-001") {
    # Read in study 759348-002
    temp_folders_study <- c("759348-002" = "dtp_hbv_hib_polio")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["759348-002"], cdi = FALSE)
    
    # Missing follow up study (adding study 759348-002)
    stu_dfs$pid <- stu_dfs$pid %>%
      left_join(select(stu_dfs2$pid, pid, elig_ma, treatmnt) %>%
                  rename(elig_ma_002 = elig_ma, treatmnt_002 = treatmnt), by = join_by(pid)) %>%
      # Incomplete treatmnt (binding treatmnt studies)
      mutate(treatmnt = as.character(glue("{treatmnt}_{treatmnt_002}"))) %>%
      # Missing cty_nam (adding from protocol) 
      mutate(cty_nam = "Germany",
             # NAs in elig_ma (replace "")
             elig_ma = replace_na(elig_ma, ""))
    stu_dfs$expo <- bind_rows(stu_dfs$expo, stu_dfs2$expo) %>%
      # Unclear vaccine (na if TREATMENT A)
      mutate(vaccine = na_if(vaccine, "TREATMENT A"))
    stu_dfs$dates <- bind_rows(stu_dfs$dates, stu_dfs2$dates)
    stu_dfs$sero <- bind_rows(stu_dfs$sero, stu_dfs2$sero) %>%
      # Surplus seroname opsono 6b 18c and 19f (eliminate CDC test)
      filter(!(seroname %in% c("OPSONO_6B CDC", "OPSONO_18C CDC", "OPSONO_19F CDC")))
  }
  
  ## 759348-003 ------------------------------------------------------------------------------------
  if(study_id == "759348-003") {
    # Missing cty_nam (adding from protocol)
    stu_dfs$pid <- stu_dfs$pid %>%
      mutate(cty_nam = "Chile",
             # NAs in elig_ma (replace "")
             elig_ma = replace_na(elig_ma, "")) 
    
    # Surplus seroname bpt (eliminate repeated test) 
    stu_dfs$sero <- filter(stu_dfs$sero, !(seroname %in% c("ANTI_BPT"))) %>%
      filter(!(serotest %in% c("901") & activity == 40))
  }
  
  ## 792014-001 ------------------------------------------------------------------------------------
  if(study_id == "792014-001") {
    # Read in study 792014-002
    temp_folders_study <- c("792014-002" = "hib_men")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["792014-002"], cdi = FALSE)
    
    # Missing follow up study (adding study 792014-002)
    stu_dfs$pid <- stu_dfs$pid %>%
      left_join(select(stu_dfs2$pid, pid, elig_ma, treatmnt) %>%
                  rename(elig_ma_002 = elig_ma, treatmnt_002 = treatmnt), by = join_by(pid)) %>%
      # Incomplete treatmnt (binding treatmnt studies)
      mutate(treatmnt = as.character(glue("{treatmnt}_{treatmnt_002}"))) %>%
      # Missing cty_nam (adding from protocol) 
      mutate(cty_nam = "Australia")
    
    # Missing type_lst (adding from dates)
    stu_dfs$dates <- stu_dfs2$dates %>%
      bind_rows(distinct(stu_dfs$expo, pid, p_rdat, activity) %>%
                  rename(raw_date = p_rdat) %>%
                  mutate(type_lst = "BL"))
    # Missing vaccine (adding from group_nb)
    stu_dfs$expo <- mutate(stu_dfs$expo, vaccine = case_when(
      vaccine == "TREATMENT A" & group_nb %in% c("1", "2", "4") ~ "mency_hib",
      vaccine == "TREATMENT A" & group_nb %in% c("3", "5") ~ "acthib",
      .default = vaccine)) %>%
      bind_rows(stu_dfs2$expo)
    stu_dfs$sero <- bind_rows(stu_dfs$sero, stu_dfs2$sero) %>%
      # Surplus seroname men (eliminate repeated test)
      filter(!(seroname %in% c("N MEN C AB", "N MEN Y AB")))
  }
  
  ## 792014-003 ------------------------------------------------------------------------------------
  if(study_id == "792014-003") {
    # Read in study 100381
    temp_folders_study <- c("100381" = "hib_men")
    stu_dfs2 <- fun_dgsk_readdfs(temp_folders_study["100381"], cdi = FALSE)
    
    # Missing follow up study (adding study 100381)
    stu_dfs$pid <- stu_dfs$pid %>%
      left_join(select(stu_dfs2$pid, pid, elig_ma, treatmnt) %>%
                  rename(elig_ma_002 = elig_ma,
                         treatmnt_002 = treatmnt), by = join_by(pid)) %>%
      # Incomplete treatmnt (binding treatmnt studies)
      mutate(treatmnt = as.character(glue("{treatmnt}_{treatmnt_002}")))
    
    # Follow up study with repeated activities (fixing to sequential activities)
    stu_dfs$expo <- stu_dfs$expo %>%
      bind_rows(mutate(stu_dfs2$expo, activity = "50")) %>%
      # Unclear vaccine (na if TREATMENT A)
      mutate(vaccine = na_if(vaccine, "TREATMENT A"))
    stu_dfs$dates <- stu_dfs$dates %>%
      bind_rows(mutate(stu_dfs2$dates, 
                       activity = case_when(activity == "10" ~ "50",
                                            activity == "20" ~ "60",
                                            activity == "240" ~ "480"))) 
    stu_dfs$sero <- stu_dfs$sero %>%
      bind_rows(mutate(stu_dfs2$sero, 
                       activity = case_when(activity == "10" ~ "50",
                                            activity == "20" ~ "60"))) %>%
      # Surplus seroname ratio and men (eliminate ratio and repeated test cutoff == 4)
      filter(!(seroname %in% c("Ratio SBA/ELISA", 
                               "N MEN Y AB", "N MEN C AB", "NMENC AB AV")))
    
  }
  
  ## 811936-001 ------------------------------------------------------------------------------------
  if(study_id == "811936-001") {
    # Missing cty_nam (adding from protocol) 
    stu_dfs$pid <- mutate(stu_dfs$pid, cty_nam = "Germany")
    
    # Surplus seroname men (eliminate old test)
    stu_dfs$sero <- filter(stu_dfs$sero, !(seroname %in% c("SBA-MENC (OLD)"))) 
  }
  
  # Return -----------------------------------------------------------------------------------------
  return(stu_dfs)
}

